15: export async function createAnnouncement(
16:   prevState: { message: string },
17:   formData: FormData
18: ) {
19:   const session = await getSession();
20:   if (!session) return { message: "Unauthorized" };
21: 
22:   const role = session.user.role.toUpperCase();
23:   if (role !== "PROFESSOR" && role !== "TEACHER" && role !== "ADMIN") {
24:     return { message: "Only instructors can post announcements." };
25:   }
26: 
27:   const parse = announcementSchema.safeParse({
28:     content: formData.get("content"),
29:     courseId: formData.get("courseId"),
30:     instituteCode: formData.get("instituteCode"),
31:   });
32: 
33:   if (!parse.success) {
34:     return { message: "Validation failed." };
35:   }
36: 
37:   const { content, courseId, instituteCode } = parse.data;
38: 
39:   try {
40:     // Verify the user is the course instructor or admin
41:     const course = await db.course.findUnique({
42:       where: { id: courseId },
43:       select: { instructorId: true, code: true, title: true },
44:     });
45: 
46:     if (!course) return { message: "Course not found." };
47: 
48:     const isInstructor = course.instructorId === session.user.id;
49:     const isAdmin = role === "ADMIN";
50: 
51:     if (!isInstructor && !isAdmin) {
52:       return { message: "You are not authorized for this course." };
53:     }
54: 
55:     await db.announcement.create({
56:       data: {
57:         content,
58:         courseId,
59:         authorId: session.user.id,
60:       },
61:     });
62: 
63:     // ── Notify all enrolled students about the new announcement ──
64:     const previewText = content.length > 60 ? content.slice(0, 57) + "…" : content;
65:     await createNotificationsForCourseStudents(courseId, {
66:       type: "ANNOUNCEMENT",
67:       title: "New Announcement",
68:       message: `New announcement in ${course.code}: ${previewText}`,
69:       link: `/${instituteCode}/announcements`,
70:     });
71: 
72:     revalidatePath(
73:       `/(dashboard)/${instituteCode}/courses/${courseId}/stream`
74:     );
75:     revalidatePath(`/(dashboard)/${instituteCode}/announcements`);
76:     return { message: "success" };
77:   } catch (error) {
78:     console.error("createAnnouncement error:", error);
79:     return { message: "Failed to post announcement." };
80:   }
81: }
