9: const instructorCreateCourseSchema = z.object({
10:   id: z.string().optional(),
11:   code: z.string().min(2, "Code must be at least 2 characters."),
12:   title: z.string().min(3, "Title must be at least 3 characters."),
13:   section: z.string().optional().default(""),
14:   subject: z.string().min(1, "Subject is required."),
15:   room: z.string().optional().default(""),
16:   description: z.string().optional().default(""),
17:   instituteCode: z.string(),
18: });
19: 
20: export async function instructorCreateCourse(
21:   prevState: { message: string; errors?: Record<string, string[]> },
22:   formData: FormData
23: ) {
24:   const user = await ensureRole(["PROFESSOR", "ADMIN"]);
25: 
26:   const parse = instructorCreateCourseSchema.safeParse({
27:     code: formData.get("code"),
28:     title: formData.get("title"),
29:     section: formData.get("section") || "",
30:     subject: formData.get("subject"),
31:     room: formData.get("room") || "",
32:     description: formData.get("description") || "",
33:     instituteCode: formData.get("instituteCode"),
34:   });
35: 
36:   if (!parse.success) {
37:     return {
38:       errors: parse.error.flatten().fieldErrors,
39:       message: "Validation failed.",
40:     };
41:   }
42: 
43:   const data = parse.data;
44: 
45:   try {
46:     const institute = await db.institute.findUnique({
47:       where: { code: data.instituteCode },
48:     });
49:     if (!institute) return { message: "Institute not found." };
50: 
51:     const codeResult = await generateCourseCode();
52:     if (!codeResult.success || !codeResult.data) {
53:       return { message: "Failed to generate course code." };
54:     }
55: 
56:     const course = await db.course.create({
57:       data: {
58:         code: data.code,
59:         courseCode: codeResult.data,
60:         title: data.title,
61:         section: data.section,
62:         subject: data.subject,
63:         room: data.room,
64:         description: data.description,
65:         instructorId: user.id, // Automatically assign to the creator
66:         instituteId: institute.id,
67:       },
68:     });
69: 
70:     // Auto-assign the instructor using the skill logic as well to keep relations clean
71:     await bulkAssignInstructor({
72:       assignments: [{ courseId: course.id, instructorId: user.id }],
73:       instituteId: institute.id,
74:     });
75: 
76:     revalidatePath(`/(dashboard)/${data.instituteCode}/courses`);
77:     return { message: "success" };
78:   } catch (error) {
79:     console.error("instructorCreateCourse error:", error);
80:     return { message: "Failed to create course." };
81:   }
82: }
