260: export async function requestEnrollment(courseId: string, instituteCode: string) {
261:   const session = await getSession();
262:   if (!session) return { success: false, error: "Unauthorized" };
263: 
264:   if (session.user.role.toUpperCase() !== "STUDENT") {
265:     return { success: false, error: "Only students can request enrollment." };
266:   }
267: 
268:   try {
269:     // Check if already enrolled or requested
270:     const existing = await db.enrollment.findUnique({
271:       where: {
272:         courseId_studentId: {
273:           courseId,
274:           studentId: session.user.id,
275:         },
276:       },
277:     });
278: 
279:     if (existing) {
280:       if (existing.status === "APPROVED") {
281:         return { success: false, error: "You are already enrolled in this course." };
282:       }
283:       if (existing.status === "PENDING") {
284:         return { success: false, error: "Your enrollment request is already pending." };
285:       }
286:       if (existing.status === "DECLINED") {
287:         // Allow re-request if previously declined
288:         await db.enrollment.update({
289:           where: { id: existing.id },
290:           data: { status: "PENDING" },
291:         });
292:         revalidatePath(`/${instituteCode}/courses`);
293:         return { success: true };
294:       }
295:     }
296: 
297:     await db.enrollment.create({
298:       data: {
299:         courseId,
300:         studentId: session.user.id,
301:         status: "PENDING",
302:       },
303:     });
304: 
305:     revalidatePath(`/${instituteCode}/courses`);
306:     return { success: true };
307:   } catch (error) {
308:     console.error("requestEnrollment error:", error);
309:     return { success: false, error: "Failed to submit enrollment request." };
310:   }
311: }
