313: export async function joinWithCode(courseCode: string, instituteCode: string) {
314:   const session = await getSession();
315:   if (!session) return { success: false, error: "Unauthorized" };
316: 
317:   if (session.user.role.toUpperCase() !== "STUDENT") {
318:     return { success: false, error: "Only students can join courses." };
319:   }
320: 
321:   try {
322:     const course = await db.course.findUnique({
323:       where: { courseCode: courseCode.toUpperCase() },
324:       select: { id: true, instituteId: true },
325:     });
326: 
327:     if (!course) {
328:       return { success: false, error: "Invalid course code. Please check and try again." };
329:     }
330: 
331:     // Verify course belongs to the student's institute
332:     const institute = await db.institute.findUnique({
333:       where: { code: instituteCode },
334:     });
335: 
336:     if (!institute || course.instituteId !== institute.id) {
337:       return { success: false, error: "This course is not available at your institute." };
338:     }
339: 
340:     // Check existing enrollment
341:     const existing = await db.enrollment.findUnique({
342:       where: {
343:         courseId_studentId: {
344:           courseId: course.id,
345:           studentId: session.user.id,
346:         },
347:       },
348:     });
349: 
350:     if (existing) {
351:       if (existing.status === "APPROVED") {
352:         return { success: false, error: "You are already enrolled." };
353:       }
354:       if (existing.status === "PENDING") {
355:         return { success: false, error: "Your request is already pending." };
356:       }
357:     }
358: 
359:     await db.enrollment.upsert({
360:       where: {
361:         courseId_studentId: {
362:           courseId: course.id,
363:           studentId: session.user.id,
364:         },
365:       },
366:       create: {
367:         courseId: course.id,
368:         studentId: session.user.id,
369:         status: "PENDING",
370:       },
371:       update: {
372:         status: "PENDING",
373:       },
374:     });
375: 
376:     revalidatePath(`/${instituteCode}/students`);
377:     revalidatePath(`/${instituteCode}/courses`);
378:     return { success: true };
379:   } catch (error) {
380:     console.error("joinWithCode error:", error);
381:     return { success: false, error: "Failed to join course." };
382:   }
383: }
