385: export async function getDiscoverableCourses(instituteCode: string) {
386:   const session = await getSession();
387:   if (!session) return [];
388: 
389:   const institute = await db.institute.findUnique({
390:     where: { code: instituteCode },
391:   });
392: 
393:   if (!institute) return [];
394: 
395:   // Get all courses at this institute that the student is NOT enrolled in
396:   const enrolledCourseIds = (
397:     await db.enrollment.findMany({
398:       where: { studentId: session.user.id },
399:       select: { courseId: true },
400:     })
401:   ).map((e) => e.courseId);
402: 
403:   return db.course.findMany({
404:     where: {
405:       instituteId: institute.id,
406:       id: { notIn: enrolledCourseIds },
407:     },
408:     include: {
409:       instructor: { select: { name: true } },
410:       _count: {
411:         select: { enrollments: { where: { status: "APPROVED" } } },
412:       },
413:     },
414:     orderBy: { title: "asc" },
415:   });
416: }
