481:     return { success: true };
482:   } catch (error) {
483:     return { success: false, error: "Failed to unarchive course." };
484:   }
485: }
486: 
487: export async function reorderCourseCards(
488:   orderedIds: string[],
489:   instituteCode: string,
490:   isStudent: boolean
491: ) {
492:   const session = await getSession();
493:   if (!session) return { success: false, error: "Unauthorized" };
494: 
495:   try {
496:     if (isStudent) {
497:       // For students: update Enrollment.displayOrderIndex
498:       await Promise.all(
499:         orderedIds.map((courseId, index) =>
500:           db.enrollment.updateMany({
501:             where: { courseId, studentId: session.user.id },
502:             data: { displayOrderIndex: index },
503:           })
504:         )
505:       );
506:     } else {
507:       // For instructors/admins: update DashboardLayout
508:       await Promise.all(
509:         orderedIds.map(async (courseId, index) => {
510:           await db.dashboardLayout.upsert({
511:             where: { userId_courseId: { userId: session.user.id, courseId } },
512:             create: { userId: session.user.id, courseId, displayOrderIndex: index },
513:             update: { displayOrderIndex: index },
514:           });
515:         })
516:       );
517:     }
518: 
519:     revalidatePath(`/${instituteCode}/students`);
520:     revalidatePath(`/${instituteCode}/courses`);
521:     return { success: true };
522:   } catch (error) {
523:     console.error("reorderCourseCards error:", error);
524:     return { success: false, error: "Failed to reorder." };
525:   }
526: }
527: 
528: export async function updateCourseCoverImage(
529:   courseId: string,
530:   coverImage: string,
531:   instituteCode: string
532: ) {
533:   const session = await getSession();
534:   if (!session) return { success: false, error: "Unauthorized" };
535: 
536:   const role = session.user.role.toUpperCase();
537:   if (role !== "PROFESSOR" && role !== "TEACHER" && role !== "ADMIN") {
538:     return { success: false, error: "Only instructors can customize course cards." };
539:   }
540: 
541:   try {
542:     await db.course.update({
543:       where: { id: courseId },
544:       data: { coverImage },
545:     });
546: 
547:     revalidatePath(`/${instituteCode}/teachers`);
548:     revalidatePath(`/${instituteCode}/students`);
549:     revalidatePath(`/${instituteCode}/courses`);
550:     return { success: true };
551:   } catch (error) {
552:     console.error("updateCourseCoverImage error:", error);
553:     return { success: false, error: "Failed to update course cover image." };
554:   }
555: }
556: 
