apps/web/src/lib/skills/bulk-assign-inst.numberedContent:
1: "use server";
2: 
3: import { db } from "@/lib/db";
4: import { executeSkill } from "./index";
5: import type { SkillResult } from "./index";
6: 
7: interface BulkAssignInput {
8:   assignments: Array<{
9:     courseId: string;
10:     instructorId: string;
11:   }>;
12:   /** Institute ID for multi-tenancy validation */
13:   instituteId: string;
14: }
15: 
16: interface BulkAssignOutput {
17:   updatedCount: number;
18:   results: Array<{
19:     courseId: string;
20:     instructorId: string;
21:     status: "success" | "error";
22:     error?: string;
23:   }>;
24: }
25: 
26: /**
27:  * Agentic Skill: Bulk Assign Instructor
28:  *
29:  * Assigns an instructor (PROFESSOR role) to one or many courses atomically.
30:  * Validates that both the instructor and course belong to the same institute.
31:  * Uses a Prisma transaction block for atomic multi-model updates.
32:  */
33: export async function bulkAssignInstructor(
34:   input: BulkAssignInput
35: ): Promise<SkillResult<BulkAssignOutput>> {
36:   return executeSkill("bulkAssignInstructor", async () => {
37:     const results: BulkAssignOutput["results"] = [];
38: 
39:     await db.$transaction(async (tx) => {
40:       for (const assignment of input.assignments) {
41:         try {
42:           // Validate instructor exists, is PROFESSOR, and belongs to this institute
43:           const instructor = await tx.user.findUnique({
44:             where: { id: assignment.instructorId },
45:             select: { id: true, role: true, instituteId: true },
46:           });
47: 
48:           if (!instructor) {
49:             results.push({
50:               ...assignment,
51:               status: "error",
52:               error: "Instructor not found",
53:             });
54:             continue;
55:           }
56: 
57:           if (
58:             instructor.role !== "PROFESSOR" &&
59:             instructor.role !== "TEACHER"
60:           ) {
61:             results.push({
62:               ...assignment,
63:               status: "error",
64:               error: `User is not an instructor (role: ${instructor.role})`,
65:             });
66:             continue;
67:           }
68: 
69:           if (instructor.instituteId !== input.instituteId) {
70:             results.push({
71:               ...assignment,
72:               status: "error",
73:               error: "Instructor does not belong to this institute",
74:             });
75:             continue;
76:           }
77: 
78:           // Validate course belongs to this institute
79:           const course = await tx.course.findUnique({
80:             where: { id: assignment.courseId },
81:             select: { id: true, instituteId: true },
82:           });
83: 
84:           if (!course) {
85:             results.push({
86:               ...assignment,
87:               status: "error",
88:               error: "Course not found",
89:             });
90:             continue;
91:           }
92: 
93:           if (course.instituteId !== input.instituteId) {
94:             results.push({
95:               ...assignment,
96:               status: "error",
97:               error: "Course does not belong to this institute",
98:             });
99:             continue;
100:           }
101: 
102:           // Perform assignment
103:           await tx.course.update({
104:             where: { id: assignment.courseId },
105:             data: { instructorId: assignment.instructorId },
106:           });
107: 
108:           results.push({ ...assignment, status: "success" });
109:         } catch (err) {
110:           results.push({
111:             ...assignment,
112:             status: "error",
113:             error: err instanceof Error ? err.message : "Unknown error",
114:           });
115:         }
116:       }
117:     });
118: 
119:     return {
120:       updatedCount: results.filter((r) => r.status === "success").length,
121:       results,
122:     };
123:   });
124: }
125:

apps/web/src/lib/skills/bulk-user-ingest.numberedContent:
1: "use server";
2: 
3: import { db } from "@/lib/db";
4: import { hash } from "bcryptjs";
5: import { executeSkill } from "./index";
6: import type { SkillResult } from "./index";
7: import {
8:   normalizeRole,
9:   DEFAULT_ROLE_PERMISSIONS,
10:   AUDIT_ACTIONS,
11: } from "@/lib/admin-types";
12: import { createAuditLog } from "@/lib/rbac";
13: 
14: // ─── Types ───
15: 
16: interface BulkUserIngestionInput {
17:   /** Raw CSV string — expects headers: name,email,uniqueId,role */
18:   csvData: string;
19:   /** Institute code to assign users to */
20:   instituteCode: string;
21:   /** Admin user performing the import (for audit trail) */
22:   actorId: string;
23: }
24: 
25: interface IngestionRecord {
26:   row: number;
27:   email: string;
28:   success: boolean;
29:   error?: string;
30:   userId?: string;
31:   temporaryPassword?: string;
32: }
33: 
34: interface BulkIngestionOutput {
35:   totalRows: number;
36:   created: number;
37:   failed: number;
38:   records: IngestionRecord[];
39: }
40: 
41: // ─── CSV Parser ───
42: 
43: function parseCSV(raw: string): Array<Record<string, string>> {
44:   const lines = raw
45:     .split(/\r?\n/)
46:     .map((l) => l.trim())
47:     .filter((l) => l.length > 0);
48: 
49:   if (lines.length < 2) {
50:     throw new Error("CSV must contain a header row and at least one data row.");
51:   }
52: 
53:   const headers = lines[0]
54:     .split(",")
55:     .map((h) => h.trim().toLowerCase().replace(/[^a-z0-9]/g, ""));
56: 
57:   const requiredHeaders = ["name", "email"];
58:   for (const req of requiredHeaders) {
59:     if (!headers.includes(req)) {
60:       throw new Error(`CSV is missing required header: "${req}". Found: ${headers.join(", ")}`);
61:     }
62:   }
63: 
64:   const rows: Array<Record<string, string>> = [];
65:   for (let i = 1; i < lines.length; i++) {
66:     const values = lines[i].split(",").map((v) => v.trim());
67:     const row: Record<string, string> = {};
68:     for (let j = 0; j < headers.length; j++) {
69:       row[headers[j]] = values[j] ?? "";
70:     }
71:     rows.push(row);
72:   }
73: 
74:   return rows;
75: }
76: 
77: // ─── Skill Implementation ───
78: 
79: /**
80:  * Agentic Skill: Bulk User Ingestion
81:  *
82:  * Parses CSV-formatted data, validates each row, detects duplicate emails,
83:  * and batch-creates user accounts with auto-generated temporary passwords.
84:  *
85:  * CSV Format:
86:  * ```
87:  * name,email,uniqueId,role
88:  * John Doe,john@school.edu,2024-001,STUDENT
89:  * Jane Smith,jane@school.edu,EMP-042,INSTRUCTOR
90:  * ```
91:  *
92:  * Can be triggered by:
93:  * - Admin bulk import UI modal
94:  * - System automation scripts
95:  * - Future LLM-driven admin workflows
96:  */
97: export async function bulkUserIngestion(
98:   input: BulkUserIngestionInput
99: ): Promise<SkillResult<BulkIngestionOutput>> {
100:   return executeSkill("bulkUserIngestion", async () => {
101:     // Validate actor is an admin
102:     const actor = await db.user.findUnique({
103:       where: { id: input.actorId },
104:       select: { role: true, id: true },
105:     });
106: 
107:     if (!actor || actor.role.toUpperCase() !== "ADMIN") {
108:       throw new Error("Unauthorized: only ADMIN users can perform bulk ingestion.");
109:     }
110: 
111:     // Resolve institute
112:     const institute = await db.institute.findUnique({
113:       where: { code: input.instituteCode },
114:     });
115: 
116:     if (!institute) {
117:       throw new Error(`Institute "${input.instituteCode}" not found.`);
118:     }
119: 
120:     // Parse CSV
121:     const csvRows = parseCSV(input.csvData);
122: 
123:     // Pre-fetch existing emails for duplicate detection
124:     const allEmails = csvRows.map((r) => r.email?.toLowerCase()).filter(Boolean);
125:     const existingUsers = await db.user.findMany({
126:       where: { email: { in: allEmails } },
127:       select: { email: true },
128:     });
129:     const existingEmailSet = new Set(existingUsers.map((u) => u.email));
130:     const batchEmailSet = new Set<string>();
131: 
132:     const records: IngestionRecord[] = [];
133:     const toCreate: Array<{
134:       name: string;
135:       email: string;
136:       uniqueId: string;
137:       role: string;
138:       hashedPassword: string;
139:       rawPassword: string;
140:       permissions: string;
141:       row: number;
142:     }> = [];
143: 
144:     for (let i = 0; i < csvRows.length; i++) {
145:       const row = csvRows[i];
146:       const rowNum = i + 2; // +2 for 1-indexed + header row
147:       const email = row.email?.toLowerCase()?.trim();
148:       const name = row.name?.trim();
149: 
150:       // Validate required fields
151:       if (!name || !email) {
152:         records.push({
153:           row: rowNum,
154:           email: email ?? "MISSING",
155:           success: false,
156:           error: "Name and email are required.",
157:         });
158:         continue;
159:       }
160: 
161:       // Validate email format
162:       if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
163:         records.push({
164:           row: rowNum,
165:           email,
166:           success: false,
167:           error: "Invalid email format.",
168:         });
169:         continue;
170:       }
171: 
172:       // DB duplicate check
173:       if (existingEmailSet.has(email)) {
174:         records.push({
175:           row: rowNum,
176:           email,
177:           success: false,
178:           error: "Email already exists in the system.",
179:         });
180:         continue;
181:       }
182: 
183:       // Batch duplicate check
184:       if (batchEmailSet.has(email)) {
185:         records.push({
186:           row: rowNum,
187:           email,
188:           success: false,
189:           error: "Duplicate email within this CSV batch.",
190:         });
191:         continue;
192:       }
193: 
194:       batchEmailSet.add(email);
195: 
196:       const normalizedRole = row.role ? normalizeRole(row.role) : "STUDENT";
197:       const dbRole = normalizedRole === "INSTRUCTOR" ? "PROFESSOR" : normalizedRole;
198:       const rawPassword =
199:         Math.random().toString(36).slice(2) +
200:         Math.random().toString(36).slice(2);
201:       const hashedPassword = await hash(rawPassword, 10);
202: 
203:       toCreate.push({
204:         name,
205:         email,
206:         uniqueId: row.uniqueid?.trim() ?? "",
207:         role: dbRole,
208:         hashedPassword,
209:         rawPassword,
210:         permissions: JSON.stringify(DEFAULT_ROLE_PERMISSIONS[normalizedRole]),
211:         row: rowNum,
212:       });
213:     }
214: 
215:     // Batch create in transaction
216:     if (toCreate.length > 0) {
217:       const created = await db.$transaction(
218:         toCreate.map((u) =>
219:           db.user.create({
220:             data: {
221:               name: u.name,
222:               email: u.email,
223:               password: u.hashedPassword,
224:               uniqueId: u.uniqueId,
225:               role: u.role,
226:               isActive: true,
227:               permissions: u.permissions,
228:               instituteId: institute.id,
229:             },
230:             select: { id: true, email: true },
231:           })
232:         )
233:       );
234: 
235:       for (let i = 0; i < created.length; i++) {
236:         records.push({
237:           row: toCreate[i].row,
238:           email: created[i].email,
239:           success: true,
240:           userId: created[i].id,
241:           temporaryPassword: toCreate[i].rawPassword,
242:         });
243:       }
244:     }
245: 
246:     // Sort records by row number for predictable output
247:     records.sort((a, b) => a.row - b.row);
248: 
249:     // Audit log
250:     await createAuditLog({
251:       adminId: input.actorId,
252:       targetId: input.actorId,
253:       action: AUDIT_ACTIONS.BULK_IMPORT,
254:       metadata: {
255:         source: "agentic-skill",
256:         totalRows: csvRows.length,
257:         created: records.filter((r) => r.success).length,
258:         failed: records.filter((r) => !r.success).length,
259:         instituteCode: input.instituteCode,
260:       },
261:     });
262: 
263:     return {
264:       totalRows: csvRows.length,
265:       created: records.filter((r) => r.success).length,
266:       failed: records.filter((r) => !r.success).length,
267:       records,
268:     };
269:   });
270: }
271:

apps/web/src/lib/skills/enrollment-manag.numberedContent:
1: "use server";
2: 
3: import { db } from "@/lib/db";
4: import { executeSkill } from "./index";
5: import type { SkillResult } from "./index";
6: 
7: type EnrollmentAction = "approve" | "decline" | "auto-process";
8: 
9: interface EnrollmentInput {
10:   enrollmentIds: string[];
11:   action: EnrollmentAction;
12:   /** Course ID for context validation */
13:   courseId: string;
14:   /** The user performing the action (for permission checks) */
15:   actorId: string;
16: }
17: 
18: interface EnrollmentOutput {
19:   processedCount: number;
20:   results: Array<{
21:     enrollmentId: string;
22:     studentId: string;
23:     status: string;
24:     action: string;
25:   }>;
26: }
27: 
28: /**
29:  * Agentic Skill: Enrollment Manager
30:  *
31:  * Processes enrollment requests: approve, decline, or auto-process based on rules.
32:  * Auto-process mode will approve all pending requests (can be extended with
33:  * capacity limits, duplicate detection, etc.)
34:  *
35:  * Can be triggered by:
36:  * - Instructor manually approving/declining from the People tab
37:  * - System triggers (e.g., scheduled batch processing)
38:  * - Future LLM integration for smart enrollment decisions
39:  */
40: export async function enrollmentManager(
41:   input: EnrollmentInput
42: ): Promise<SkillResult<EnrollmentOutput>> {
43:   return executeSkill("enrollmentManager", async () => {
44:     const results: EnrollmentOutput["results"] = [];
45: 
46:     // Validate the actor has permission over this course
47:     const course = await db.course.findUnique({
48:       where: { id: input.courseId },
49:       select: { instructorId: true, instituteId: true },
50:     });
51: 
52:     if (!course) {
53:       throw new Error("Course not found");
54:     }
55: 
56:     // Check that the actor is the course instructor or an admin
57:     const actor = await db.user.findUnique({
58:       where: { id: input.actorId },
59:       select: { role: true, instituteId: true },
60:     });
61: 
62:     if (!actor) {
63:       throw new Error("Actor not found");
64:     }
65: 
66:     const isInstructor = course.instructorId === input.actorId;
67:     const isAdmin = actor.role === "ADMIN";
68: 
69:     if (!isInstructor && !isAdmin) {
70:       throw new Error("Unauthorized: only the course instructor or admin can manage enrollments");
71:     }
72: 
73:     if (input.action === "auto-process") {
74:       // Auto-process: approve all pending enrollments for this course
75:       const pendingEnrollments = await db.enrollment.findMany({
76:         where: {
77:           courseId: input.courseId,
78:           status: "PENDING",
79:         },
80:         select: { id: true, studentId: true },
81:       });
82: 
83:       await db.enrollment.updateMany({
84:         where: {
85:           courseId: input.courseId,
86:           status: "PENDING",
87:         },
88:         data: { status: "APPROVED" },
89:       });
90: 
91:       for (const enrollment of pendingEnrollments) {
92:         results.push({
93:           enrollmentId: enrollment.id,
94:           studentId: enrollment.studentId,
95:           status: "APPROVED",
96:           action: "auto-process",
97:         });
98:       }
99:     } else {
100:       // Manual approve/decline specific enrollments
101:       const newStatus = input.action === "approve" ? "APPROVED" : "DECLINED";
102: 
103:       for (const enrollmentId of input.enrollmentIds) {
104:         const enrollment = await db.enrollment.findUnique({
105:           where: { id: enrollmentId },
106:           select: { id: true, studentId: true, courseId: true, status: true },
107:         });
108: 
109:         if (!enrollment || enrollment.courseId !== input.courseId) {
110:           continue;
111:         }
112: 
113:         if (enrollment.status !== "PENDING") {
114:           results.push({
115:             enrollmentId: enrollment.id,
116:             studentId: enrollment.studentId,
117:             status: enrollment.status,
118:             action: `skipped (already ${enrollment.status})`,
119:           });
120:           continue;
121:         }
122: 
123:         await db.enrollment.update({
124:           where: { id: enrollmentId },
125:           data: { status: newStatus },
126:         });
127: 
128:         results.push({
129:           enrollmentId: enrollment.id,
130:           studentId: enrollment.studentId,
131:           status: newStatus,
132:           action: input.action,
133:         });
134:       }
135:     }
136: 
137:     return {
138:       processedCount: results.length,
139:       results,
140:     };
141:   });
142: }
